      return `<section class="sc-card" data-quantity-preview><h2>${esc(local('计算数量预览','Calculation quantity preview','計算数量の確認'))}</h2><p>${esc(local('业务需求','Business quantity','業務物量'))}: ${esc(audit.canRun?number(audit.businessTotal):String(audit.businessTotal))} ${esc(audit.unit)} · ${esc(local('用于计算','Used by model','モデル使用量'))}: ${audit.modelTotal==null?'—':esc(number(audit.modelTotal))} ${esc(audit.unit)} · ${esc(local('调整行','Adjusted rows','調整行'))}: ${audit.adjustedBusinessRows}</p><p class="sc-note">${audit.canRun?esc(local('本次数量可精确表示；无需有损量化。','Quantities are exactly representable; no lossy adjustment is needed.','数量は正確に表現できます。')):esc(audit.reason==='SUPPLY_JOINT_ZERO_DEMAND'?local('本研究范围内的物量为零，无需计算。','Quantity is zero in this scope; no calculation is needed.','この範囲の物量はゼロで、計算は不要です。'):local('当前数量不在安全计算范围；可保存草稿，不会自动削减需求或放宽约束。','Quantities are outside the safe model range; save a draft without reducing demand or relaxing constraints.','数量が安全な計算範囲外です。下書きとして保存できます。'))} ${audit.canRun?`1/${audit.scale}`:''}</p>${detail}</section>`;
